class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        """
        方法一：XOR 位元運算（最優）
        時間複雜度: O(n)
        空間複雜度: O(1)
        """
        result = 0
        for num in nums:
            result ^= num
        return result

    def singleNumber_oneliner(self, nums: List[int]) -> int:
        """
        方法一：XOR - 一行寫法
        """
        from functools import reduce
        return reduce(lambda x, y: x ^ y, nums)

    def singleNumber_set(self, nums: List[int]) -> int:
        """
        方法二：HashSet
        時間複雜度: O(n)
        空間複雜度: O(n)
        """
        seen = set()
        for num in nums:
            if num in seen:
                seen.remove(num)
            else:
                seen.add(num)
        return seen.pop()

    def singleNumber_math(self, nums: List[int]) -> int:
        """
        方法四：數學方法
        2 * (a + b + c) - (a + a + b + b + c) = c
        """
        return 2 * sum(set(nums)) - sum(nums)

    def singleNumber_dict(self, nums: List[int]) -> int:
        """
        方法三：HashMap 計數
        """
        from collections import Counter
        count = Counter(nums)
        for num, freq in count.items():
            if freq == 1:
                return num

