#include <vector>
#include <unordered_set>
using namespace std;

class Solution {
public:
    /**
     * 方法一：XOR 位元運算（最優）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    int singleNumber(vector<int>& nums) {
        int result = 0;
        for (int num : nums) {
            result ^= num;
        }
        return result;
    }

    /**
     * 方法二：HashSet
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    int singleNumber_set(vector<int>& nums) {
        unordered_set<int> seen;
        for (int num : nums) {
            if (seen.count(num)) {
                seen.erase(num);
            } else {
                seen.insert(num);
            }
        }
        return *seen.begin();
    }
};

