import java.util.HashSet;
import java.util.Set;

class Solution {
    /**
     * 方法一：XOR 位元運算（最優）
     * 時間複雜度: O(n)
     * 空間複雜度: O(1)
     */
    public int singleNumber(int[] nums) {
        int result = 0;
        for (int num : nums) {
            result ^= num;
        }
        return result;
    }

    /**
     * 方法二：HashSet
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    public int singleNumber_set(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int num : nums) {
            if (seen.contains(num)) {
                seen.remove(num);
            } else {
                seen.add(num);
            }
        }
        return seen.iterator().next();
    }
}

